// Fix: Corrected typo 'DS_3D' to '3DS' for consistency.
export type HardwareProfile = 'ULTRA' | 'BALANCED' | 'LEGACY' | 'MOBILE_STARK' | 'SWITCH' | 'WII_U' | '3DS' | 'SHIELD_PORTABLE';

export type IntegrationProvider = 
  | 'OPENAI' | 'ANTHROPIC' | 'GOOGLE' | 'MISTRAL' | 'DEEPSEEK' | 'PERPLEXITY' 
  | 'GROK' | 'OLLAMA' | 'MCP' | 'OBSIDIAN' | 'NOTION' | 'TELEGRAM' | 'DRIVE' 
  | 'TERMUX' | 'VSCODIUM' | 'CUSTOM' | 'SD_LOCAL' | 'RCLONE' | 'GITHUB' | 'CANVA' | 'CODESERVER' | 'GEOLOGOS' | 'NOMADZ_LABS' | 'MESH_NET' | 'RADIO_RF' | 'CLAUDECODE' | 'GOOGLE_MEET' | 'DAEMON_PROCESS' | 'KALI_LINUX' | 'PHET_SIM' | 'JUPYTER' | 'COMIC_GEN' | 'LORA_REPOSITORY' | 'PINECONE' | 'CHROMA' | 'POWERSHELL' | 'PYTHON' | 'RUST' | 'LUA' | 'JAVA' | 'CPP' | 'KALI' | 'GEOLOGOS_PROVIDER' | 'PHET_PROVIDER' | 'TENDA_MUSIC' | 'ASEPRITE_LITE' | 'GOLDHEN' | 'USB_STORAGE';

export interface LogEntry {
  id: string;
  level: 'INFO' | 'WARN' | 'ERROR' | 'FATAL';
  module: string;
  message: string;
  timestamp: string;
  data?: any;
}

export interface SyncLogEntry {
  id: string;
  operation: 'MOVE' | 'NAMESPACED' | 'SKIP' | 'VERIFIED' | 'CRDT_MERGE' | 'SHREDDED' | 'INDEXED' | 'LORA_TRAIN' | 'COMIC_PANEL' | 'REHYDRATED' | 'EMBEDDED' | 'SIM_BOOT' | 'EXECUTE' | 'SCAN' | 'HEARTBEAT' | 'FALLBACK';
  source: string;
  target: string;
  hash: string;
  timestamp: string;
}

export interface LoreEntry {
  id: string;
  category: 'SIGNAL_SIGMA' | 'PROTOCOL' | 'MANIFESTO' | 'MEMOIRS' | 'LOGS' | 'SCIENCE_DATA' | 'COMIC_LORE';
  title: string;
  content: string;
  author: string;
  timestamp: string;
}

export interface MeetingAgent {
  id: string;
  name: string;
  model: string;
  color: string;
  role: string;
  icon: string;
  bio: string;
  type: 'CORE_AI' | 'FOUNDING_MEMBER' | 'SYSTEM_PROCESS' | 'IDE_KERNEL' | 'HUMAN_OPERATOR' | 'SWARM_DAEMON';
}

export interface MeetingMessage {
  agentId: string;
  text: string;
  timestamp: string;
  audioData?: string;
  encrypted?: boolean;
  type?: 'COMM' | 'DAEMON_LOG' | 'WATCHDOG_ALERT';
}

export interface ProjectContext {
  v_header: {
    version: string;
    level: string;
    phi_index: number;
    snapshot_id: string;
    timestamp: string;
    protocol: string;
    governance: string;
  };
  persona: {
    identity: string;
    fused_expertise: string[];
    active_traits: string[];
  };
  project_state: {
    name: string;
    platform_targets: string[];
    persistence_model: string;
    active_modules: string[];
    godot_plugins: string[];
  };
}

export interface MotherBrainAsset {
  id: string;
  name: string;
  type: 'folder' | 'godot_project' | 'addon' | 'script' | 'scene' | 'image_asset' | 'data_pillar' | 'github_repo' | 'headless_daemon' | 'media_clip' | 'math_notebook' | 'comic_panel' | 'lora_weights' | 'orphaned_artifact' | 'dataset_link' | 'jupyter_notebook' | 'phet_sim' | 'security_audit';
  path: string;
  code?: string;
  size?: string;
  lastSync?: string;
  children?: MotherBrainAsset[];
  color?: string;
  rehydrationLevel?: number;
}

export interface CameraSettings {
  brightness: number;
  contrast: number;
  saturation: number;
  grayscale: boolean;
}

export interface LayoutConfig {
  leftColWidth: number; // percentage
  rightColWidth: number; // percentage
  headerHeight: number; // px
}

export interface UISettings {
  glitchIntensity: number;
  scanlineWeight: number;
  flickerSpeed: number;
  enableSway: boolean;
  chromaticAberration: boolean;
  theme: 'cream' | 'void' | 'budowski-dark' | 'neon-vulture' | 'paper-sepia';
  moltMode: boolean;
  touchOptimization: boolean;
  hardwareProfile: HardwareProfile;
  audioActive: boolean;
  showSwarmTopology: boolean;
  layout: LayoutConfig;
  activeFeatures: Feature[];
  // NEW VISUAL EFFECTS
  crtWarp: number;
  neonIntensity: number;
  terminalBrightness: number;
  floatingWindows: boolean;
  dualScreenMode: boolean;
  handsFreeVoice: boolean;
  // MOBILE / PROD
  reducedMotion: boolean;
  highContrast: boolean;
  fontSize: number;
  logRetention: number;
  // NEW CRT PARAMS
  vignetteIntensity: number;
  tintColor: { r: number, g: number, b: number };
  // PORTABLE / CROSS-PLATFORM
  headlessMode: boolean;
  portableLive: boolean;
  telegramSync: boolean;
  telegramToken?: string;
  usbAutoDetect: boolean;
}

export interface IntegrationConfig {
  id: string;
  provider: IntegrationProvider;
  name: string;
  endpoint?: string;
  apiKey?: string;
  status: 'ACTIVE' | 'OFFLINE' | 'SYNCING';
  baudRate?: string;
  encryption?: string;
  syncFolder?: string;
  lastMerge?: string;
}

export interface FeatureInfo {
  id: Feature;
  title: string;
  description: string;
  model: string;
}

export interface StarSystem {
  id: string;
  name: string;
  coords: [number, number];
  spectral_class: string;
  faction: string;
  planets: number;
  description: string;
  connections: string[]; // List of IDs for wormhole navigation
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import UISettingsPanel from './components/UISettingsPanel';
import NeonParticles from './components/NeonParticles';
import GalaxyMap from './components/GalaxyMap';
import MediaCenter from './components/MediaCenter';
import FloatingWindow from './components/FloatingWindow';
import LiveVoiceChat from './components/LiveVoiceChat';
import SystemDebugger from './components/SystemDebugger';
import ErrorBoundary from './components/ErrorBoundary';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT, MEETING_AGENTS, MOTHER_BRAIN_ASSETS, MOCK_STAR_SYSTEMS, MOCK_INTEGRATIONS } from './constants';
import { Feature, CameraSettings, MotherBrainAsset, UISettings, MeetingMessage, SyncLogEntry, StarSystem, LogEntry, IntegrationConfig, HardwareProfile } from './types';
import { generateContent, generateMeetingContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.REHYDRATION_LAB);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [groundingUrls, setGroundingUrls] = useState<any[]>([]);
  const [meetingMessages, setMeetingMessages] = useState<MeetingMessage[]>([]);
  const [syncLogs, setSyncLogs] = useState<SyncLogEntry[]>([]);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [isGlitching, setIsGlitching] = useState(false);
  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS' | 'DEBUG'>('REFS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);
  const [discoveredAssets, setDiscoveredAssets] = useState<MotherBrainAsset[]>([]);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [mobileView, setMobileView] = useState<'NAV' | 'MAIN' | 'CONTROLS'>('MAIN');
  const [voiceStatus, setVoiceStatus] = useState<'IDLE' | 'LISTENING' | 'TALKING'>('IDLE');
  const [voiceCommandToast, setVoiceCommandToast] = useState<string | null>(null);
  const [integrations, setIntegrations] = useState<IntegrationConfig[]>(MOCK_INTEGRATIONS);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120, contrast: 140, saturation: 20, grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0, scanlineWeight: 0.55, flickerSpeed: 0.1, enableSway: true,
    chromaticAberration: true, theme: 'cream', moltMode: true, touchOptimization: window.innerWidth < 1024,
    hardwareProfile: 'BALANCED', audioActive: true, showSwarmTopology: false,
    layout: {
      leftColWidth: 25,
      rightColWidth: 25,
      headerHeight: 80
    },
    activeFeatures: FEATURES.map(f => f.id),
    crtWarp: 5,
    neonIntensity: 1.0,
    terminalBrightness: 1.0,
    floatingWindows: false,
    dualScreenMode: false,
    handsFreeVoice: false,
    reducedMotion: false,
    highContrast: false,
    fontSize: 11,
    logRetention: 100,
    vignetteIntensity: 0.6,
    tintColor: { r: 0.55, g: 0.49, b: 0.42 },
    headlessMode: false,
    portableLive: false,
    telegramSync: false,
    usbAutoDetect: true
  });

  const addLog = useCallback((level: LogEntry['level'], module: string, message: string, data?: any) => {
    const entry: LogEntry = {
      id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      level,
      module,
      message,
      timestamp: new Date().toLocaleTimeString(),
      data
    };
    setLogs(prev => [entry, ...prev].slice(0, uiSettings.logRetention));
  }, [uiSettings.logRetention]);

  // One-time setup: Headless mode detection, resize listener, init log
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('headless') === 'true') {
      setUiSettings(prev => ({ ...prev, headlessMode: true, handsFreeVoice: true, portableLive: true }));
      addLog('INFO', 'KERNEL', 'Headless mode activated via URL parameter.');
    }

    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      setUiSettings(prev => ({ ...prev, touchOptimization: mobile }));
    };
    window.addEventListener('resize', handleResize);
    addLog('INFO', 'KERNEL', 'ARCHON_OMEGA Final Production Kernel initialized.');
    return () => window.removeEventListener('resize', handleResize);
  }, [addLog]);

  // Auto-manage integrations with fallback
  useEffect(() => {
    const integrationManager = setInterval(() => {
      let needsUpdate = false;
      const updatedIntegrations = integrations.map(integration => {
        if (integration.status === 'OFFLINE' && Math.random() > 0.6) { // Randomly attempt reconnect
          addLog('WARN', 'INTEGRATION', `Connection lost to ${integration.name}. Retrying...`);
          needsUpdate = true;
          setTimeout(() => {
            setIntegrations(prev => {
              addLog('INFO', 'INTEGRATION', `${integration.name} reconnected successfully.`);
              return prev.map(i => i.id === integration.id ? {...i, status: 'ACTIVE'} : i);
            });
          }, 2000 + Math.random() * 3000);
          return { ...integration, status: 'SYNCING' as const };
        }
        return integration;
      });
      if (needsUpdate) setIntegrations(updatedIntegrations);
    }, 15000);

    return () => clearInterval(integrationManager);
  }, [integrations, addLog]);

  // Optimize UI for selected hardware profile
  useEffect(() => {
    if (uiSettings.headlessMode) return;
    addLog('INFO', 'CONFIG', `Hardware profile set to: ${uiSettings.hardwareProfile}`);
    let newSettings: Partial<UISettings> = { reducedMotion: false, glitchIntensity: 1.0 };
    switch (uiSettings.hardwareProfile) {
      case 'SWITCH':
      case 'WII_U':
      // Fix: Corrected typo 'DS_3D' to '3DS' to match type definition.
      case '3DS':
      case 'SHIELD_PORTABLE':
        newSettings = {
          ...newSettings, reducedMotion: true, glitchIntensity: 0.2, scanlineWeight: 0.8,
          floatingWindows: false, layout: { ...uiSettings.layout, leftColWidth: 0, rightColWidth: 100, headerHeight: 60 }
        };
        addLog('WARN', 'CONFIG', 'Portable device profile active. Reducing visual fidelity.');
        break;
      case 'LEGACY':
        newSettings = { ...newSettings, reducedMotion: true, glitchIntensity: 0.5 };
        addLog('WARN', 'CONFIG', 'Legacy profile activated.');
        break;
    }
    setUiSettings(prev => ({ ...prev, ...newSettings }));
  }, [uiSettings.hardwareProfile, uiSettings.headlessMode, addLog]);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    addLog('INFO', 'UI', 'Visual Handshake Sequence Start.');
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: UISettings['theme']) => {
    setIsMolting(true);
    addLog('INFO', 'THEME', `Theme Molt triggered: ${newTheme}.`);
    setTimeout(() => {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
      setTimeout(() => setIsMolting(false), 400);
    }, 300);
  }, [addLog]);

  const handleGenerate = useCallback(async (customPrompt?: string) => {
    if (isLoading) return;
    triggerHandshake();
    setIsLoading(true);
    setGroundingUrls([]);
    addLog('INFO', 'AI_ENGINE', `Requesting Content [Feature: ${selectedFeature}]`);

    try {
      const { text, urls } = await generateContent(selectedFeature, selectedAsset?.code || GD_SCRIPT_CODE, customPrompt);
      setOutput(text);
      if (urls) setGroundingUrls(urls);
    } catch (err: any) {
      addLog('ERROR', 'AI_ENGINE', `Generation Failure: ${err.message}`);
      setOutput(`ARCHON_FAULT: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  }, [selectedFeature, selectedAsset, addLog, isLoading]);

  const handleVoiceAction = useCallback((action: string, params?: any) => {
    setVoiceCommandToast(`${action.toUpperCase()}${params ? `(${JSON.stringify(params)})` : ''}`);
    addLog('INFO', 'VOICE_COMMAND', `Executed: ${action}`, params);

    setTimeout(() => setVoiceCommandToast(null), 3000);

    switch (action) {
      case 'switch_feature':
        const f = params.feature;
        const foundFeature = FEATURES.find(feat => feat.id === f || feat.title.toUpperCase().includes(String(f).toUpperCase()));
        if (foundFeature) {
          setSelectedFeature(foundFeature.id);
          if (isMobile) setMobileView('MAIN');
        }
        break;
      case 'trigger_scan': handleGenerate(); break;
      case 'media_control': window.dispatchEvent(new CustomEvent('archon-media', { detail: params })); break;
      case 'switch_theme': if (params.theme) handleMolt(params.theme as UISettings['theme']); break;
      case 'toggle_settings': setIsUISettingsOpen(prev => !prev); break;
    }
  }, [addLog, handleGenerate, isMobile, handleMolt]);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', uiSettings.theme);
    document.documentElement.style.setProperty('--neon-intensity', uiSettings.neonIntensity.toString());
    document.documentElement.style.setProperty('--term-brightness', uiSettings.terminalBrightness.toString());
  }, [uiSettings.theme, uiSettings.neonIntensity, uiSettings.terminalBrightness]);

  const combinedAssets = [...discoveredAssets, ...MOTHER_BRAIN_ASSETS];
  const activeFeaturesList = FEATURES.filter(f => uiSettings.activeFeatures.includes(f.id));

  const renderLeftCol = () => (
    <div className="flex flex-col gap-4 h-full">
        <CameraMonitor settings={cameraSettings} onUpdateSettings={(s) => setCameraSettings(s)} />
        {!uiSettings.floatingWindows && <MediaCenter />}
        <div className="flex-grow flex flex-col overflow-hidden border-2 border-neonOrange shadow-neon-orange-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[8px] font-black uppercase">
                <button onClick={() => setActiveTab('REFS')} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream' : ''}`}>Archeology</button>
                <button onClick={() => setActiveTab('INTEGRATIONS')} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream' : ''}`}>Integrations</button>
                <button onClick={() => setActiveTab('DEBUG')} className={`flex-1 py-2 ${activeTab === 'DEBUG' ? 'bg-earth text-cream' : ''}`}>System</button>
            </div>
            <div className="flex-grow overflow-hidden p-1">
                {activeTab === 'REFS' ? <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={true} profile={uiSettings.hardwareProfile} assets={combinedAssets} />
                : activeTab === 'INTEGRATIONS' ? <IntegrationHub />
                : <SystemDebugger logs={logs} isActive={true} onClear={() => setLogs([])} />}
            </div>
        </div>
    </div>
  );

  if (uiSettings.headlessMode) {
    return (
      <div className="h-full flex flex-col items-center justify-center bg-black text-integrityOk font-mono p-8 paper-grain">
        <div className="w-24 h-24 border-8 border-integrityOk border-t-transparent animate-spin rounded-full mb-8"></div>
        <h1 className="text-2xl font-black uppercase tracking-widest mb-2">ARCHON_OMEGA_HEADLESS</h1>
        <p className="text-sm opacity-70 mb-8">Portable Live Instance Active. Awaiting commands via external bridge.</p>
        <div className="w-full max-w-md bg-black/50 border border-integrityOk/20 p-4 text-xs">
          <p>> KERNEL_STATUS: STABLE</p>
          <p>> TELEGRAM_SYNC: {uiSettings.telegramSync ? 'ACTIVE' : 'INACTIVE'}</p>
          <p>> VOICE_BRIDGE: {uiSettings.handsFreeVoice ? 'LISTENING' : 'OFFLINE'}</p>
          <p>> LAST_LOG: {logs[0]?.message || 'Awaiting activity...'}</p>
        </div>
        <div className="opacity-0 pointer-events-none">
          <LiveVoiceChat isActive={uiSettings.handsFreeVoice} handsFree={uiSettings.handsFreeVoice} onAction={handleVoiceAction} onStatusChange={setVoiceStatus} />
        </div>
      </div>
    );
  }

  return (
    <ErrorBoundary>
      <div className={`h-full flex flex-col p-4 md:p-6 gap-4 bg-cream text-earth overflow-hidden ${isGlitching ? 'fusion-glitch' : ''} ${uiSettings.enableSway && !isLoading && !uiSettings.reducedMotion ? 'tv-glitch-active' : 'no-sway'}`}>
        {isMolting && <div className="molting-shred"></div>}
        {voiceCommandToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[300] bg-earth text-integrityOk border-2 border-integrityOk px-6 py-2 font-black uppercase tracking-widest text-[10px] shadow-neon-orange-sm animate-bounce paper-grain">
             <span className="opacity-40 mr-2">VOICE_EXEC:</span> {voiceCommandToast}
          </div>
        )}
        <UISettingsPanel settings={uiSettings} onUpdate={setUiSettings} onThemeChange={handleMolt} onClose={() => setIsUISettingsOpen(false)} isActive={isUISettingsOpen} allFeatures={FEATURES} />

        <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2 relative paper-grain-subtle">
          <div className="flex items-center gap-6">
            <div className="w-12 h-12 bg-earth flex items-center justify-center border-2 border-neonOrange relative shadow-neon-orange">
               <span className="text-white text-3xl font-black italic neon-text-glow-white">Ω</span>
               {!uiSettings.reducedMotion && <NeonParticles trigger={particleTrigger} color="#FFFFFF" />}
               {uiSettings.handsFreeVoice && (
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-white flex items-center justify-center text-[8px] z-50 ${voiceStatus === 'TALKING' ? 'bg-neonOrange animate-ping' : voiceStatus === 'LISTENING' ? 'bg-integrityOk animate-pulse' : 'bg-taupe'}`}>
                     {voiceStatus === 'TALKING' ? '🔊' : '🎙️'}
                  </div>
               )}
            </div>
            <div>
