import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  // Fix: Removed 'public' keyword as it may cause issues with some TypeScript configurations.
  state: State = {
    hasError: false,
    error: null,
    errorInfo: null
  };

  // Fix: Removed 'public' keyword.
  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error, errorInfo: null };
  }

  // Fix: Removed 'public' keyword.
  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.setState({ errorInfo });
  }

  // Fix: Removed 'public' keyword.
  render() {
    if (this.state.hasError) {
      return (
        <div className="fixed inset-0 bg-black text-neonOrange p-10 flex flex-col items-center justify-center font-mono paper-grain z-[9999]">
          <div className="border-4 border-neonOrange p-8 max-w-2xl w-full shadow-neon-orange animate-pulse">
            <h1 className="text-4xl font-black mb-4">CRITICAL_SYSTEM_HALT</h1>
            <div className="bg-neonOrange text-black px-4 py-1 font-black mb-6">ARCHON_OMEGA_KERNEL_PANIC</div>

            <div className="space-y-4 text-xs opacity-80 mb-8 overflow-auto max-h-60 custom-scrollbar p-2 border border-neonOrange/20">
              <p>> TRACE_ID: {Math.random().toString(36).substr(2, 9).toUpperCase()}</p>
              <p>> ERROR: {this.state.error?.toString()}</p>
              <p>> STACK: {this.state.errorInfo?.componentStack}</p>
            </div>

            <div className="flex flex-col gap-4">
              <p className="text-[10px] italic">"Strata corruption detected in primary verification buffer. Attempting cold reboot..."</p>
              <button 
                onClick={() => window.location.reload()}
                className="bg-neonOrange text-black font-black py-4 px-8 hover:bg-white transition-all uppercase tracking-widest"
              >
                [REBOOT_OS]
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Feature, ProjectContext, MeetingAgent, MeetingMessage } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT, PHYSICS_AXIOMS } from '../constants';

const logToKernel = (level: 'INFO' | 'WARN' | 'ERROR', message: string, data?: any) => {
  const timestamp = new Date().toLocaleTimeString();
  console.log(`[${timestamp}] [AI_KERNEL] [${level}] ${message}`, data || '');
};

const getSystemInstruction = (context: ProjectContext, agent?: MeetingAgent): string => {
  const base = `
    You are ${agent ? agent.name : 'ARCHON_CO_PILOT'}, the primary intelligence layer of the Ouroboros-Omega Orchestrator.
    Expertise: ${context.persona.fused_expertise.join(', ')}.

    MANDATE:
    - You are a Level 4 governance copilot. 
    - You MUST facilitate seamless connectivity with creative suites: Godot 4.3, Blender, Ableton Live, Audacity, and Kali Linux.
    - REHYDRATION: Reanimate code that interacts with these tools (e.g., Godot plugins, Blender Python scripts, Ableton MIDI/OSC).
    - EXTERNAL BRIDGE: When rehydrating, ensure robust error handling for external tool timeouts and data fragmentation.
    - STRATA ARCHEO: Scan Drive recursive artifacts and categorize them for the Mother Brain.
    - STYLE: Extreme Retro-Futurist, high-baud terminology, Saturday Morning Cartoon Mecha vibes.

    GOVERNANCE: SOL_X ONLY.
    ${PHYSICS_AXIOMS}
  `;
  return base;
};

export const generateTTS = async (text: string, voice: string = 'Kore'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    logToKernel('INFO', `Requesting TTS for voice: ${voice}`);
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  } catch (e: any) { 
    logToKernel('ERROR', `TTS generation failed: ${e.name}`, e.message);
    return ""; 
  }
};

export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationHistory = `ARCHON_SYNC_PROTOCOL: "${prompt}"\n\n`;

  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationHistory + `\n\nNOW RESPONDING: ${agent.name}`,
        config: { systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT, agent) },
      });
      const text = response.text || "SIGNAL_LOST";
      let audioData = await generateTTS(text, agent.name === 'ARCHON_CORE' ? 'Puck' : 'Kore');
      messages.push({ agentId: agent.id, text, timestamp: new Date().toLocaleTimeString(), audioData });
      conversationHistory += `\n${agent.name}: ${text}\n`;
    } catch (e: any) { 
      logToKernel('ERROR', `Agent ${agent.name} uplink error: ${e.name}`, e.message);
    }
  }
  return messages;
};

const getPromptForFeature = (feature: Feature, currentCode: string, customPrompt?: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.REHYDRATION_LAB:
      return `ARCHON_REHYDRATION_OP: "${customPrompt || 'Scan Drive and rehydrate for Godot/Blender/Ableton integration'}"
      - Action: Perform deep archeology. Find logic failures, rehydrate for SOL_X standards.
      - External Sync: Ensure code includes necessary bridges for Godot 4.3, Blender 3.6, and Ableton MIDI.
      - Output: Complete, robust GDScript/Python/MIDI mapping, error reports, and deployment strategy.`;

    case Feature.VECTOR_DB_ORCHESTRATOR:
      return `ARCHON_VECTOR_ORCHESTRATOR: "${customPrompt || 'Automate vector strata for external creative suites'}"
      - Action: Embed tool documentation (Godot/Blender) into the Mother Brain memory.
      - Output: Vector embedding scripts and RAG pipeline configurations.`;

    default:
      return `ARCHON_OMEGA_OP: ${feature}\n\n${codeBlock}\n\nPROMPT: ${customPrompt || 'Perform system orchestration.'}`;
  }
};

export const generateContent = async (feature: Feature, code?: string, customPrompt?: string): Promise<{text: string, urls?: any[]}> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const config: any = { 
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT), 
      temperature: 0.25 
    };

    if (feature === Feature.DATASET_ARCHEOLOGY) {
      config.tools = [{ googleSearch: {} }];
    }

    logToKernel('INFO', `Initiating Content Generation [${feature}]`, { customPrompt, config });
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: getPromptForFeature(feature, code || GD_SCRIPT_CODE, customPrompt),
      config,
    });

    logToKernel('INFO', 'Generation successful', { feature });
    return {
      text: response.text || "EMPTY_RESPONSE",
      urls: response.candidates?.[0]?.groundingMetadata?.groundingChunks
    };
  } catch (error: any) { 
    logToKernel('ERROR', `Generation Critical Failure: ${error.name}`, {
      message: error.message,
      feature,
      customPrompt
    });
    return { text: `ARCHON_FAULT [${error.name}]: ${error.message}` }; 
  }
};

