export const generateContent = async (feature: Feature, code?: string, customPrompt?: string): Promise<{text: string, urls?: any[]}> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const config: any = { 
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT), 
      temperature: 0.3 
    };

    let prompt = `ARCHON_OMEGA_OP: ${feature}\n\n`;
    if (feature === Feature.PRODUCTION_STUDIO) {
      prompt += `ACTION: Synthesis of 16-bit asset metadata.
      - Input: ${customPrompt || 'Generic Signalverse artifact'}
      - Target: TKinter Bridge / Cosmic AI
      - Protocol: SQLite WAL Append`;
    } else {
      prompt += `PROMPT: ${customPrompt || 'Perform system orchestration.'}`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return {
      text: response.text || "EMPTY_RESPONSE",
      urls: response.candidates?.[0]?.groundingMetadata?.groundingChunks
    };
  } catch (error: any) { 
    logToKernel('ERROR', `AI Fault: ${error.name}`, error.message);
    return { text: `ARCHON_FAULT [${error.name}]: ${error.message}` }; 
  }
};

